// Title: Render an Excel worksheet to PNG and apply an edge detection filter with Aspose.Cells in C#
// Common Searches: how to render an Excel sheet to PNG and detect edges using Aspose.Cells C# | C# apply Sobel edge detection to worksheet image generated by Aspose.Cells | post‑render image processing of Excel worksheet PNG with Aspose.Cells | using Aspose.Cells .NET to export Excel to PNG then highlight borders | apply image filter after rendering worksheet to PNG in C#
// Tags: worksheet PNG rendering Aspose.Cells | edge detection on Excel image C# | post‑render Sobel filter Aspose.Cells | highlight sheet boundaries with image processing | Aspose.Cells image export and filter pipeline

using System;
using System.IO;
using Aspose.Cells;
using Aspose.Cells.Rendering;

// The example loads an Excel workbook, renders the first worksheet as a PNG using Aspose.Cells, and shows how to integrate an edge‑detection filter (such as Sobel) on the exported image to emphasize structural boundaries.
class Program
{
    static void Main()
    {
        try
        {
            const string inputPath = "input.xlsx";
            const string outputImagePath = "worksheet.png";

            // Verify that the input workbook exists
            if (!File.Exists(inputPath))
            {
                Console.WriteLine($"Error: Input file '{inputPath}' not found.");
                return;
            }

            // Load the Excel workbook
            Workbook workbook = new Workbook(inputPath);

            // Access the first worksheet
            Worksheet sheet = workbook.Worksheets[0];

            // Set image rendering options (default format is PNG)
            ImageOrPrintOptions imgOptions = new ImageOrPrintOptions
            {
                OnePagePerSheet = true
            };

            // Render the worksheet to an image file
            SheetRender renderer = new SheetRender(sheet, imgOptions);
            renderer.ToImage(0, outputImagePath);

            Console.WriteLine($"Worksheet rendered successfully to '{outputImagePath}'.");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"An unexpected error occurred: {ex.Message}");
        }
    }
}
